steps.script:
var fd = tree.root.get_node("/root/Main/FormationsDialog")
var sb = fd.scroll_container.get_v_scroll_bar()
return sb.max_value > sb.page

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var rows = ScrollFocusChain.collect_focusables(fd.scroll_container)
var escapes = 0
for i in range(rows.size() - 1):
	if rows[i].find_valid_focus_neighbor(SIDE_BOTTOM) != rows[i + 1]:
		escapes += 1
return escapes

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var rows = ScrollFocusChain.collect_focusables(fd.scroll_container)
return str(rows[rows.size() - 1].find_valid_focus_neighbor(SIDE_BOTTOM).name)

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var f = fd.gui_get_focus_owner()
return str(f.text) if f != null else "NULL"

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var rows = ScrollFocusChain.collect_focusables(fd.scroll_container)
return fd.gui_get_focus_owner() == rows[rows.size() - 1]

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var rows = ScrollFocusChain.collect_focusables(fd.scroll_container)
var first_res = -1
for i in range(rows.size()):
	if rows[i].has_meta("reserves_section"):
		first_res = i
		break
if first_res <= 0:
	return false
rows[first_res - 1].grab_focus()
return true

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var f = fd.gui_get_focus_owner()
return f != null and f.has_meta("reserves_section")

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var f = fd.gui_get_focus_owner()
f.button_pressed = not f.button_pressed
return fd.reserves.size()

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var rows = ScrollFocusChain.collect_focusables(fd.scroll_container)
rows[0].grab_focus()
return rows.size()

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var f = fd.gui_get_focus_owner()
return str(f.name) if f != null else "NULL"

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var sc = fd.scroll_container
return sc.scroll_vertical >= int(sc.get_v_scroll_bar().max_value - sc.get_v_scroll_bar().page) - 2

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var f = fd.gui_get_focus_owner()
return str(f.name) if f != null else "NULL"
